/* ============================================================================
   HDT · Hojas de Consumo — Relación Equipo <-> Producto (Listados Ortopedia)  (Fase 6)
   Ejecutar DESPUÉS de 01..09:  node run-db.js
   ----------------------------------------------------------------------------
   Qué códigos de producto pertenecen a cada equipo. Sirve para NO permitir en la
   hoja de consumo una combinación (Código, N° equipo) que no exista.
   EquipoCodigo = normalizado sin NUT- (igual que cat.Equipo). Datos de los
   'Listados de Ortopedia Español 2026' (un Excel por equipo; PINES mapeado por tamaño).
   Idempotente: ON CONFLICT DO NOTHING.
   ============================================================================ */

CREATE TABLE IF NOT EXISTS cat.EquipoProducto (
    EquipoCodigo   VARCHAR(40)  NOT NULL,
    ProductoCodigo VARCHAR(60)  NOT NULL,
    PRIMARY KEY (EquipoCodigo, ProductoCodigo)
);
CREATE INDEX IF NOT EXISTS IX_EquipoProducto_Equipo ON cat.EquipoProducto (EquipoCodigo);

ON CONFLICT (EquipoCodigo, ProductoCodigo) DO NOTHING;
